            if (iamRoleArn) influxPoint.tag('iamRoleArn', iamRoleArn);
            if (externalId) influxPoint.tag('externalId', externalId);
            if (ingestion) influxPoint.tag('ingestion', ingestion);
            if (dlq) influxPoint.tag('dlq', dlq);
        }
        return influxPoint;
    }

    public static dbModelToEntity({
        platform,
        accountId,
        region,
        iamRoleArn,
        externalId,
        ingestion,
        dlq,
        businessID,
        measurementId,
    }: {
        [x: string]: any;
    }) {
        return new DatastoreAccessInformation({
            platform,
            accountId,
            region,
            iamRoleArn,
            externalId,
            ingestion,
            dlq,
            businessID,
            measurementId,
        });
    }

    private static buildTrustPolicy(accountId: string, externalId: string) {
        return {
            Version: '2012-10-17',
            Statement: [
                {
                    Effect: 'Allow',
                    Principal: {
                        AWS: `arn:aws:iam::${accountId}:root`,
                    },
                    Action: 'sts:AssumeRole',
                    Condition: {
                        StringEquals: {
                            'sts:ExternalId': externalId,
                        },
                    },
                },
            ],
        };
    }

    private static buildPermissionsPolicy(businessID: string) {
        const bucket = process.env.DB_MEASUREMENT_BUCKET_NAME;
        const dlqBucket = process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME;
        return {
            Version: '2012-10-17',
            Statement: [
                {
                    Sid: 'IngestionAccess',
                    Effect: 'Allow',
                    Action: ['s3:PutObject', 's3:GetObject', 's3:AbortMultipartUpload', 's3:ListBucket'],
                    Resource: [`arn:aws:s3:::${bucket}`, `arn:aws:s3:::${bucket}/${businessID}/*`],
                },
                {
                    Sid: 'DlqAccess',
                    Effect: 'Allow',
                    Action: ['s3:GetObject', 's3:ListBucket'],
                    Resource: [`arn:aws:s3:::${dlqBucket}`, `arn:aws:s3:::${dlqBucket}/${businessID}/*`],
                },
            ],
        };
    }

    private static iamClient() {
        return new IAMClient({ region: process.env.AWS_REGION || 'us-east-1' });
    }

    public static async setupAccess(dbAccessInformation: DatastoreAccessInformation) {
        const { accountId, businessID, measurementId } = dbAccessInformation;
        const platform = (dbAccessInformation.platform || SupportedDatastores.s3).toString().toLowerCase();
        const region = dbAccessInformation.region || process.env.AWS_REGION || 'us-east-1';

        if (platform === SupportedDatastores.s3) {
            try {
                const externalId = randomUUID();
                const roleName = `datastore-${businessID}-${measurementId}`;
                const iam = DatastoreAccessInformation.iamClient();
                const trustPolicy = DatastoreAccessInformation.buildTrustPolicy(accountId, externalId);

                const createRoleResp = await iam.send(
                    new CreateRoleCommand({
                        RoleName: roleName,
                        AssumeRolePolicyDocument: JSON.stringify(trustPolicy),
                        Description: `Enterprise datastore measurement role for business ${businessID}`,
                    })
                );

                await iam.send(
                    new PutRolePolicyCommand({
                        RoleName: roleName,
                        PolicyName: `${roleName}-policy`,
                        PolicyDocument: JSON.stringify(
                            DatastoreAccessInformation.buildPermissionsPolicy(businessID)
                        ),
                    })
                );

                const bucket = process.env.DB_MEASUREMENT_BUCKET_NAME;
                const dlqBucket = process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME;

                dbAccessInformation.platform = SupportedDatastores.s3;
                dbAccessInformation.region = region;
                dbAccessInformation.externalId = externalId;
                dbAccessInformation.iamRoleArn = createRoleResp.Role?.Arn;
                dbAccessInformation.ingestion = `s3://${bucket}/${businessID}/`;
                dbAccessInformation.dlq = `s3://${dlqBucket}/${businessID}/`;

                return dbAccessInformation;
            } catch (e) {
                if (e?.name === 'MalformedPolicyDocument' || e?.Code === 'MalformedPolicyDocument') {
                    throw new BadRequestException(`accountId: ${accountId} is invalid`);
                }
                throw e;
            }
        }
        return dbAccessInformation;
    }

    public static async updateAccess(dbAccessInformation: DatastoreAccessInformation) {
        const { accountId, iamRoleArn, externalId } = dbAccessInformation;
        if (!iamRoleArn || !externalId || !accountId) {
            return dbAccessInformation;
        }
        try {
            const roleName = iamRoleArn.split('/').pop();
            const iam = DatastoreAccessInformation.iamClient();
            const trustPolicy = DatastoreAccessInformation.buildTrustPolicy(accountId, externalId);
            await iam.send(
                new UpdateAssumeRolePolicyCommand({
                    RoleName: roleName,
                    PolicyDocument: JSON.stringify(trustPolicy),
                })
            );
            return dbAccessInformation;
        } catch (e) {
            if (e?.name === 'MalformedPolicyDocument' || e?.Code === 'MalformedPolicyDocument') {
                throw new BadRequestException(`accountId: ${accountId} is invalid`);
            }
            throw e;
        }
    }
}

import { Tag } from '@aws-sdk/client-ec2';
import { PutObjectCommand, S3Client } from '@aws-sdk/client-s3';
import { randomUUID } from 'crypto';
import EventEmitter from 'events';
import { AuditService } from '../../audit/audit.service';
import { AuditScope } from '../../audit/entities/audit.interface';
import { InfluxService } from '../../influx/influx.service';
import { MeasurementFormat } from './measurement.interface';

const eventEmitter = new EventEmitter();
export class StandardMeasurementEntity implements MeasurementFormat {
    public timeStamp?: string;
    public dimensionId?: string;
    public businessID: string;
    public applicationId?: string;
    public serviceId?: string;
    public recordValue: number;
    public metadata: Record<string, string>;
    public _measurement: string;
    public static allowedTags = ['enterpriseApplicationId', 'enterpriseServiceId', 'enterpriseDimensionId'];

    constructor(measurement: MeasurementFormat) {
        if (measurement.timeStamp) {
            this.timeStamp = measurement.timeStamp;
        } else {
            this.timeStamp = new Date().toISOString();
        }
        this.dimensionId = measurement.dimensionId;
        this.applicationId = measurement.applicationId;
        this.serviceId = measurement.serviceId;
        this.recordValue = measurement.recordValue;
        this.metadata = measurement.metadata;
        this.businessID = measurement.businessID;
        this._measurement = measurement._measurement;
    }
    static publish(publishRequest: MeasurementFormat) {
        eventEmitter.emit('standardMeasurements', publishRequest);
        return {
            message: 'published',
            id: randomUUID(),
            data: [publishRequest],
        };
    }
    static subscribe(influxService: InfluxService) {
        eventEmitter.on('standardMeasurements', async (measurementFormat: MeasurementFormat) => {
            const point = MeasurementFormat.getPointForm(measurementFormat, influxService);
            try {
                await influxService.loadPoints(`${process.env.STAGE}-usage-data`, `enterprise`, [point]);
            } catch (err) {
                AuditService.publishEvent({
                    data: [{ err }],
                    message: 'Failed to index Measurement',
                    topic: AuditScope.ERROR,
                });
            }
        });
    }
    static awsTagKeyReducer(Tags: Tag[]) {
        if (Tags) {
            return Tags.reduce((acc, { Key, Value }): any => {
                if (StandardMeasurementEntity.allowedTags.includes(Key)) {
                    acc[Key] = Value;
                }
                return acc;
            }, {});
        } else {
            return {};
        }
    }

    /**
     * Normalize an S3 key or URI to a bucket-relative object key.
     */
    static toRelativeS3Key(s3Key: string): string {
        if (!s3Key) {
            return s3Key;
        }
        let key = s3Key;
        if (key.startsWith('s3://')) {
            const withoutScheme = key.slice('s3://'.length);
            const slashIdx = withoutScheme.indexOf('/');
            key = slashIdx >= 0 ? withoutScheme.slice(slashIdx + 1) : '';
        } else if (key.startsWith('/')) {
            key = key.replace(/^\/+/, '');
        }
        return key;
    }

    /**
     * Write a failed datastore usage record to the configured DLQ bucket.
     * DLQ object key mirrors the source key with a `.message.text` suffix.
     */
    static async publishFailureToDLQ({
        message,
        s3Key,
        error,
        metadata,
    }: {
        message: unknown;
        s3Key: string;
        error?: unknown;
        metadata?: Record<string, unknown>;
    }) {
        const relativeKey = StandardMeasurementEntity.toRelativeS3Key(s3Key);
        const dlqKey = `${relativeKey}.message.text`;
        const errMessage =
            error instanceof Error ? error.message : error !== undefined ? String(error) : 'Unknown error';
        const body = JSON.stringify({
            failedInput: message,
            s3Key,
            error: errMessage,
            processingMetadata: {
                failedAt: new Date().toISOString(),
                relativeKey,
                dlqKey,
                ...(metadata || {}),
            },
        });
        const region = process.env.AWS_REGION || 'us-east-1';
        const client = new S3Client({ region });
        await client.send(
            new PutObjectCommand({
                Bucket: process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME,
                Key: dlqKey,
                Body: body,
                ContentType: 'text/plain',
            })
        );
        return { message: 'Published failure to DLQ', key: dlqKey };
    }
}

