        eventEmitter.emit('standardMeasurements', publishRequest);
        return {
            message: 'published',
            id: randomUUID(),
            data: [publishRequest],
        };
    }
    static subscribe(influxService: InfluxService) {
        eventEmitter.on('standardMeasurements', async (measurementFormat: MeasurementFormat) => {
            const point = MeasurementFormat.getPointForm(measurementFormat, influxService);
            try {
                await influxService.loadPoints(`${process.env.STAGE}-usage-data`, `enterprise`, [point]);
            } catch (err) {
                AuditService.publishEvent({
                    data: [{ err }],
                    message: 'Failed to index Measurement',
                    topic: AuditScope.ERROR,
                });
            }
        });
    }
    static awsTagKeyReducer(Tags: Tag[]) {
        if (Tags) {
            return Tags.reduce((acc, { Key, Value }): any => {
                if (StandardMeasurementEntity.allowedTags.includes(Key)) {
                    acc[Key] = Value;
                }
                return acc;
            }, {});
        } else {
            return {};
        }
    }

    /**
     * Normalize an S3 key or URI to a bucket-relative object key.
     */
    static toRelativeS3Key(s3Key: string): string {
        if (!s3Key) {
            return s3Key;
        }
        let key = s3Key;
        if (key.startsWith('s3://')) {
            const withoutScheme = key.slice('s3://'.length);
            const slashIdx = withoutScheme.indexOf('/');
            key = slashIdx >= 0 ? withoutScheme.slice(slashIdx + 1) : '';
        } else if (key.startsWith('/')) {
            key = key.replace(/^\/+/, '');
        }
        return key;
    }

    /**
     * Write a failed datastore usage record to the configured DLQ bucket.
     * DLQ object key mirrors the source key with a `.message.text` suffix.
     */
    static async publishFailureToDLQ({
        message,
        s3Key,
        error,
        metadata,
    }: {
        message: unknown;
        s3Key: string;
        error?: unknown;
        metadata?: Record<string, unknown>;
    }) {
        const relativeKey = StandardMeasurementEntity.toRelativeS3Key(s3Key);
        const dlqKey = `${relativeKey}.message.text`;
        const errMessage =
            error instanceof Error ? error.message : error !== undefined ? String(error) : 'Unknown error';
        const body = JSON.stringify({
            failedInput: message,
            s3Key,
            error: errMessage,
            processingMetadata: {
                failedAt: new Date().toISOString(),
                relativeKey,
                dlqKey,
                ...(metadata || {}),
            },
        });
        const region = process.env.AWS_REGION || 'us-east-1';
        const client = new S3Client({ region });
        await client.send(
            new PutObjectCommand({
                Bucket: process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME,
                Key: dlqKey,
                Body: body,
                ContentType: 'text/plain',
            })
        );
        return { message: 'Published failure to DLQ', key: dlqKey };
    }
}

